    {
        "name": "add",
        "description": "Add two numbers",
        "inputSchema": {
            "type": "object",
            "properties": {
                "a": {"type": "number"},
                "b": {"type": "number"}
            },
            "required": ["a", "b"]
        }
    },
    {
        "name": "fail_once",
        "description": "Fails on first call, succeeds on subsequent calls",
        "inputSchema": {
            "type": "object",
            "properties": {}
        }
    }
]

