import { SANDBOX_TOOL_NAME } from '$lib/constants';
import { SandboxService } from '$lib/services/sandbox.service';
import { beforeEach, describe, expect, it } from 'vitest';

const run = (code: string, timeoutMs?: number) =>
	SandboxService.executeTool(SANDBOX_TOOL_NAME, {
		code,
		...(timeoutMs !== undefined ? { timeout_ms: timeoutMs } : {})
	});

describe('sandbox service', () => {
	beforeEach(async () => {
		const { settingsStore } = await import('$lib/stores/settings/index.svelte');

		settingsStore.config = {
			...settingsStore.config,
			symbolicMathEnabled: true
		};
	});

	it('executes plain JavaScript', async () => {
		const reply = await run('return 1 + 1;');

		expect(reply.isError).toBe(false);
		expect(reply.content).toContain('=> 2');
	});

	it('exposes nerdamer for symbolic computation', async () => {
		const reply = await run("return nerdamer.diff('sin(x)/x', 'x').toString();");

		expect(reply.isError).toBe(false);
		expect(reply.content).toContain('cos(x)');
	});

	it('computes exact rational arithmetic', async () => {
		const reply = await run("return nerdamer('1/3 + 1/6').toString();");

		expect(reply.isError).toBe(false);
		expect(reply.content).toContain('=> 1/2');
	});

	it('proves a polynomial identity symbolically', async () => {
		const reply = await run(
			"return nerdamer('expand((1+x*y)^3 - (1 + 3*x*y + 3*x^2*y^2 + x^3*y^3))').toString();"
		);

		expect(reply.isError).toBe(false);
		expect(reply.content).toContain('=> 0');
	});

	it('blocks network egress in the worker via CSP', async () => {
		const reply = await run(
			"try { await fetch('https://example.com/'); return 'leaked'; } catch { return 'blocked'; }"
		);

		expect(reply.isError).toBe(false);
		expect(reply.content).toContain('=> blocked');
	});

	it('enforces the timeout on runaway code', async () => {
		const reply = await run('while (true) {}', 500);

		expect(reply.isError).toBe(true);
		expect(reply.content).toContain('timed out');
	});
});

// Guards the rename of `showModelOrgNameInTrigger` onto `showModelOrgName`.
// The persisted config always holds the legacy key, so a value it carries moves
// over, while a config that already set the new key keeps its own value. The
// legacy key is removed so it does not stay orphaned in localStorage.

import { CONFIG_LOCALSTORAGE_KEY } from '$lib/constants';
import { MigrationService } from '$lib/services/migration.service';
import { settingsStore } from '$lib/stores/settings/index.svelte';
import { beforeEach, describe, expect, it } from 'vitest';

const MODEL_ORG_NAME_KEY_MIGRATION_ID = 'model-org-name-key-v1';

async function seedConfig(stored: Record<string, unknown>) {
	localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(stored));

	const migration = MigrationService.getMigrations().find(
		(m) => m.id === MODEL_ORG_NAME_KEY_MIGRATION_ID
	);

	await migration?.run();
	settingsStore.initialize();
}

function persisted(): Record<string, unknown> {
	return JSON.parse(localStorage.getItem(CONFIG_LOCALSTORAGE_KEY) ?? '{}');
}

describe('showModelOrgNameInTrigger rename', () => {
	beforeEach(() => {
		localStorage.removeItem(CONFIG_LOCALSTORAGE_KEY);
		MigrationService.resetState();
		settingsStore.initialize();
	});

	it('carries an enabled trigger over to the selector-wide key', async () => {
		await seedConfig({ showModelOrgNameInTrigger: true });
		expect(settingsStore.config.showModelOrgName).toBe(true);
	});

	it('carries a disabled trigger over to the selector-wide key', async () => {
		await seedConfig({ showModelOrgNameInTrigger: false });
		expect(settingsStore.config.showModelOrgName).toBe(false);
	});

	it('keeps an explicit user preference over the legacy key', async () => {
		await seedConfig({ showModelOrgName: false, showModelOrgNameInTrigger: true });
		expect(settingsStore.config.showModelOrgName).toBe(false);
	});

	it('drops the legacy key from the persisted config', async () => {
		await seedConfig({ showModelOrgNameInTrigger: true });
		expect(persisted().showModelOrgNameInTrigger).toBeUndefined();
	});

	it('leaves the selector-wide key on its default when nothing is stored', async () => {
		await seedConfig({});
		expect(settingsStore.config.showModelOrgName).toBe(true);
	});
});

// Guards the unfolding of `renderContentAsRawText` back onto the two
// per-surface render keys. The single toggle carried user content and
// thinking at once, so only the user key is restored from it and thinking
// returns to its own default. The toggle is removed from the persisted
// config so it does not stay orphaned in localStorage.

import { CONFIG_LOCALSTORAGE_KEY } from '$lib/constants';
import { MigrationService } from '$lib/services/migration.service';
import { settingsStore } from '$lib/stores/settings/index.svelte';
import { beforeEach, describe, expect, it } from 'vitest';

const RENDER_KEYS_MIGRATION_ID = 'render-keys-unfold-v1';

async function seedConfig(stored: Record<string, unknown>) {
	localStorage.setItem(CONFIG_LOCALSTORAGE_KEY, JSON.stringify(stored));

	const migration = MigrationService.getMigrations().find((m) => m.id === RENDER_KEYS_MIGRATION_ID);

	await migration?.run();
	settingsStore.initialize();
}

function persisted(): Record<string, unknown> {
	return JSON.parse(localStorage.getItem(CONFIG_LOCALSTORAGE_KEY) ?? '{}');
}

describe('renderContentAsRawText unfolding', () => {
	beforeEach(() => {
		localStorage.removeItem(CONFIG_LOCALSTORAGE_KEY);
		MigrationService.resetState();
		settingsStore.initialize();
	});

	it('maps raw text to user content as plain text', async () => {
		await seedConfig({ renderContentAsRawText: true });
		expect(settingsStore.config.renderUserContentAsMarkdown).toBe(false);
	});

	it('maps markdown to user content as markdown', async () => {
		await seedConfig({ renderContentAsRawText: false });
		expect(settingsStore.config.renderUserContentAsMarkdown).toBe(true);
	});

	it('leaves thinking on its own default', async () => {
		await seedConfig({ renderContentAsRawText: true });
		expect(settingsStore.config.renderThinkingAsMarkdown).toBe(true);
	});

	it('keeps an explicit user preference over the toggle', async () => {
		await seedConfig({ renderContentAsRawText: true, renderUserContentAsMarkdown: true });
		expect(settingsStore.config.renderUserContentAsMarkdown).toBe(true);
	});

	it('drops the toggle from the persisted config', async () => {
		await seedConfig({ renderContentAsRawText: true });
		expect(persisted().renderContentAsRawText).toBeUndefined();
	});

	it('leaves both surfaces on markdown when nothing is stored', async () => {
		await seedConfig({});
		expect(settingsStore.config.renderUserContentAsMarkdown).toBe(true);
		expect(settingsStore.config.renderThinkingAsMarkdown).toBe(true);
	});
});

